//! harvest: Automated fixture generator and dataset extractor.
//!
//! Harvests multi-file git diffs with old and new side snapshots from any
//! repository into a golden corpus directory (`fixture/diff.patch`,
//! `fixture/old/`, `fixture/new/`, `meta.json`) conforming to
//! tests/AGENTS.md. The recorded revision is pinned to absolute short commit
//! ids or `<ref>^!`, so a golden can be regenerated byte-for-byte by
//! re-running the engine over the frozen inputs.

mod args;
mod fixture;
mod git;

#[cfg(test)]
mod tests;

use std::{
    collections::HashMap,
    env,
    fs::{self, File},
    io::Write,
    process,
};

use clap::Parser;
use diffuse::git::{ENGINE_CONTEXT, load_git_repo};
use diffuse_git::Repository;
use serde::Serialize;

use args::{Args, exclude_pathspecs};
use fixture::{FixtureOutput, is_diffuse_repo, resolve_golden_name};
use git::{resolve_revision, target_revision_endpoint};

fn main() {
    let args = Args::parse();

    for dir in &args.directory {
        if let Err(e) = env::set_current_dir(dir) {
            eprintln!(
                "harvest: cannot change directory to '{}': {e}",
                dir.display()
            );
            process::exit(1);
        }
    }

    let repo_root = args
        .repo
        .unwrap_or_else(|| env::current_dir().expect("valid current dir"));
    let in_diffuse = is_diffuse_repo(&repo_root);
    let golden_name = resolve_golden_name(args.tag.as_deref(), args.output.as_deref(), in_diffuse)
        .unwrap_or_else(|e| {
            eprintln!("harvest: {e}");
            process::exit(1);
        });

    let mut exclude = args.exclude.clone();
    if in_diffuse
        && !exclude
            .iter()
            .any(|p| p == "tests/golden" || p == "tests/golden/")
    {
        exclude.push("tests/golden".to_string());
    }

    // `WORKTREE` diffs the (uncommitted) working tree against HEAD; any
    // other revision expression is pinned to absolute commit ids up front so
    // the diff and the recorded revision are both fixed.
    let worktree = args.revision == "WORKTREE";
    let resolved_revision = if worktree {
        args.revision.clone()
    } else {
        resolve_revision(&repo_root, &args.revision).unwrap_or_else(|e| {
            eprintln!("harvest: {e}");
            process::exit(1);
        })
    };
    let base_args: Vec<String> = if worktree {
        Vec::new()
    } else {
        vec![resolved_revision.clone()]
    };

    let git_res = match load_git_repo(
        &repo_root,
        &base_args,
        &exclude_pathspecs(&exclude),
        false,
        ENGINE_CONTEXT,
    ) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("harvest: {e}");
            process::exit(1);
        }
    };

    let revision = if worktree {
        let head = Repository::open(&repo_root)
            .ok()
            .and_then(|r| r.rev_to_short_hash("HEAD"))
            .unwrap_or_default();
        if head.is_empty() {
            "WORKTREE".to_string()
        } else {
            head
        }
    } else {
        resolved_revision.clone()
    };

    let notes_path = args
        .notes_file
        .unwrap_or_else(diffuse::core::notes::default_notes_path);

    let (harvested_notes, repo_key, rev_key) = if notes_path.is_file() {
        use diffuse::core::repo::ReviewTargetNotesExt;
        let db = diffuse::core::notes::load_notes(&notes_path);
        let repo = diffuse::core::repo::Repo::from_root(&repo_root);
        let target =
            diffuse::core::repo::ReviewTarget::from_repo_args(repo, base_args.clone(), false);
        let rk = target.repo_key().unwrap_or("diffuse");
        let matched_revs = target.matched_rev_keys(&db);
        let mut notes_map: diffuse::core::notes::NotesDB = HashMap::new();
        if let Some(rev_map) = db.get(rk) {
            let mut harvested_revs = HashMap::new();
            for rev in &matched_revs {
                if let Some(file_notes) = rev_map.get(*rev)
                    && !file_notes.is_empty()
                {
                    harvested_revs.insert((*rev).to_string(), file_notes.clone());
                }
            }
            if !harvested_revs.is_empty() {
                notes_map.insert(rk.to_string(), harvested_revs);
            }
        }
        if notes_map.is_empty() {
            (None, None, None)
        } else {
            let target_rev = target.rev_key().unwrap_or("");
            (
                Some(notes_map),
                Some(rk.to_string()),
                Some(target_rev.to_string()),
            )
        }
    } else {
        (None, None, None)
    };

    let fixture = FixtureOutput {
        diff: git_res.diff,
        new_content: git_res.new_content,
        old_content: git_res.old_content,
        revision,
        repo_key: repo_key.clone(),
        rev_key: rev_key.clone(),
        notes: harvested_notes.clone(),
    };

    if let Some(out_path) = args.output {
        let is_json = out_path.extension().is_some_and(|ext| ext == "json")
            || out_path.to_string_lossy().ends_with(".json.gz");
        if is_json {
            let json = serde_json::to_string_pretty(&fixture).expect("serialize fixture");
            if out_path.extension().is_some_and(|ext| ext == "gz") {
                let file = File::create(&out_path).expect("create output file");
                let mut encoder = flate2::write::GzEncoder::new(file, flate2::Compression::best());
                encoder.write_all(json.as_bytes()).expect("write gzip data");
                encoder.finish().expect("finish gzip compression");
            } else {
                fs::write(&out_path, json).expect("write output file");
            }
            eprintln!(
                "Harvested {} files to {}",
                fixture.new_content.len(),
                out_path.display()
            );
        } else {
            // Directory structure: meta.json at the corpus root, frozen
            // inputs under fixture/ (diff.patch, notes.json, and sparse
            // old//new/ trees mirroring workspace-relative paths so the
            // harness can pass them straight to --old-dir/--new-dir).
            let corpus_dir = out_path;
            let fixture_dir = corpus_dir.join("fixture");
            let old_dir = fixture_dir.join("old");
            let new_dir = fixture_dir.join("new");
            fs::create_dir_all(&old_dir).expect("create fixture/old dir");
            fs::create_dir_all(&new_dir).expect("create fixture/new dir");

            // Write diff.patch
            fs::write(fixture_dir.join("diff.patch"), &fixture.diff)
                .expect("write fixture/diff.patch");

            let mut all_paths: Vec<String> = fixture
                .new_content
                .keys()
                .chain(fixture.old_content.keys())
                .cloned()
                .collect();
            all_paths.sort();
            all_paths.dedup();

            #[derive(Serialize)]
            struct MetaOutput {
                revision: String,
                #[serde(skip_serializing_if = "Option::is_none")]
                repo_key: Option<String>,
                #[serde(skip_serializing_if = "Option::is_none")]
                rev_key: Option<String>,
            }

            // Note: no path list — the file set is derived from
            // fixture/diff.patch itself (new side keyed by `path`, old side
            // by `old_path`, exactly as the content maps above are keyed).
            for p in all_paths {
                if let Some(old_str) = fixture.old_content.get(&p) {
                    let target = old_dir.join(&p);
                    if let Some(parent) = target.parent() {
                        fs::create_dir_all(parent).expect("create old parent dirs");
                    }
                    fs::write(&target, old_str).expect("write old file");
                }
                if let Some(new_str) = fixture.new_content.get(&p) {
                    let target = new_dir.join(&p);
                    if let Some(parent) = target.parent() {
                        fs::create_dir_all(parent).expect("create new parent dirs");
                    }
                    fs::write(&target, new_str).expect("write new file");
                }
            }

            let meta = MetaOutput {
                revision: fixture.revision,
                repo_key,
                rev_key,
            };
            let meta_json = serde_json::to_string_pretty(&meta).expect("serialize meta.json");
            fs::write(corpus_dir.join("meta.json"), meta_json).expect("write meta.json");

            if let Some(ref notes) = harvested_notes {
                let notes_json = serde_json::to_string_pretty(notes).expect("serialize notes.json");
                fs::write(fixture_dir.join("notes.json"), notes_json)
                    .expect("write fixture/notes.json");
                let note_count: usize = notes
                    .values()
                    .flat_map(|revs| revs.values())
                    .flat_map(|files| files.values())
                    .map(Vec::len)
                    .sum();
                eprintln!(
                    "Harvested {} review notes to {}",
                    note_count,
                    fixture_dir.join("notes.json").display()
                );
            }

            eprintln!(
                "Harvested {} files to {}",
                fixture.new_content.len(),
                corpus_dir.display()
            );
        }
    } else {
        let json = serde_json::to_string_pretty(&fixture).expect("serialize fixture");
        println!("{json}");
    }

    if (in_diffuse || args.tag.is_some())
        && let Some(ref golden) = golden_name
    {
        let repo = Repository::open(&repo_root).unwrap_or_else(|e| {
            eprintln!("harvest: cannot open repository to tag: {e}");
            process::exit(1);
        });

        // Determine single vs multi-commit range
        if let Some((left, right)) = resolved_revision
            .split_once("...")
            .or_else(|| resolved_revision.split_once(".."))
        {
            let beg_tag = format!("{golden}-beg");
            let end_tag = format!("{golden}-end");
            repo.create_tag(&beg_tag, left).unwrap_or_else(|e| {
                eprintln!("harvest: cannot create tag '{beg_tag}': {e}");
                process::exit(1);
            });
            repo.create_tag(&end_tag, right).unwrap_or_else(|e| {
                eprintln!("harvest: cannot create tag '{end_tag}': {e}");
                process::exit(1);
            });
            let short_left = repo
                .rev_to_short_hash(left)
                .unwrap_or_else(|| left.to_string());
            let short_right = repo
                .rev_to_short_hash(right)
                .unwrap_or_else(|| right.to_string());
            eprintln!(
                "Tagged range {short_left}..{short_right} as '{beg_tag}' and '{end_tag}' in {}",
                repo_root.display()
            );
        } else {
            let target_endpoint = target_revision_endpoint(&resolved_revision);
            repo.create_tag(golden, target_endpoint)
                .unwrap_or_else(|e| {
                    eprintln!("harvest: cannot create tag '{golden}': {e}");
                    process::exit(1);
                });
            let short = repo
                .rev_to_short_hash(target_endpoint)
                .unwrap_or_else(|| target_endpoint.to_string());
            eprintln!(
                "Tagged commit {short} as '{golden}' in {}",
                repo_root.display()
            );
        }
    }
}
